CREATE TABLE communication_messages (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), body text NOT NULL, status text NOT NULL CHECK (status IN ('queued','sending','completed','failed')), created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE communication_recipients (message_id text NOT NULL REFERENCES communication_messages(id), phone text NOT NULL, student_id text REFERENCES students(id), status text NOT NULL CHECK (status IN ('queued','sent','failed')), attempts int NOT NULL DEFAULT 0, last_error text, sent_at timestamptz, PRIMARY KEY(message_id, phone));
